    <div>
      <ul>
        {items.map((e) => (
          <li key={e.id} style={{ borderBottom: '1px solid #E5E0DC' }} className="flex justify-between p-3">
            <div>
              <p className="font-bold">{e.name}</p>
              <p className="text-gray-500">{e.sets} series</p>
            </div>
            <button style={{ color: '#C43004' }} onClick={() => onEdit(e.id)}>Editar</button>
          </li>
        ))}
      </ul>
      <p className="text-sm text-gray-500">Volumen total: 2480kg</p>
    </div>
  )
}
